 {
     FileProvider = new Microsoft.Extensions.FileProviders.PhysicalFileProvider(
         Path.Combine(builder.Environment.ContentRootPath, "Content")),
     RequestPath = "/Content"
 });

 // Serve legacy Scripts folder  
