using System;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain any leftover notifications from other tests (static queue)
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _service.Dispose();
        }

        [Fact]
        public void SendNotification_ValidParameters_EnqueuesNotification()
        {
            // Arrange & Act
            _service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithDisplayName_GeneratesCorrectMessage()
        {
            // Arrange & Act
            _service.SendNotification("Course", "101", "Chemistry 101", EntityOperation.CREATE, "System");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("New Course 'Chemistry 101' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
        {
            // Arrange & Act
            _service.SendNotification("Student", "42", EntityOperation.UPDATE, "System");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student (ID: 42) has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
        {
            // Arrange & Act
            _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Department 'Engineering' has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateOperation_GeneratesUpdateMessage()
        {
            // Arrange & Act
            _service.SendNotification("Instructor", "3", "Dr. Smith", EntityOperation.UPDATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Instructor 'Dr. Smith' has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            // Arrange & Act
            _service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToCurrentTime()
        {
            // Arrange
            var before = DateTime.Now.AddSeconds(-1);

            // Act
            _service.SendNotification("Student", "1", EntityOperation.CREATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.True(notification.CreatedAt >= before);
            Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            // Act
            var notification = _service.ReceiveNotification();

            // Assert
            Assert.Null(notification);
        }

        [Fact]
        public void ReceiveNotification_MultipleMessages_ReturnsFIFOOrder()
        {
            // Arrange
            _service.SendNotification("Student", "1", EntityOperation.CREATE, "Admin");
            _service.SendNotification("Course", "2", EntityOperation.UPDATE, "Admin");
            _service.SendNotification("Department", "3", EntityOperation.DELETE, "Admin");

            // Act & Assert
            var first = _service.ReceiveNotification();
            Assert.Equal("Student", first.EntityType);
            Assert.Equal("1", first.EntityId);

            var second = _service.ReceiveNotification();
            Assert.Equal("Course", second.EntityType);
            Assert.Equal("2", second.EntityId);

            var third = _service.ReceiveNotification();
            Assert.Equal("Department", third.EntityType);
            Assert.Equal("3", third.EntityId);

            var fourth = _service.ReceiveNotification();
            Assert.Null(fourth);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // Act & Assert (no-op implementation should not throw)
            var exception = Record.Exception(() => _service.MarkAsRead(1));
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_OverloadWithoutDisplayName_Works()
        {
            // Arrange & Act
            _service.SendNotification("Student", "5", EntityOperation.CREATE, "TestUser");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("5", notification.EntityId);
            Assert.Contains("Student (ID: 5)", notification.Message);
        }

        [Fact]
        public void SendNotification_EmptyDisplayName_UsesIdInMessage()
        {
            // Arrange & Act
            _service.SendNotification("Student", "7", "   ", EntityOperation.UPDATE, "Admin");

            // Assert
            var notification = _service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student (ID: 7) has been updated", notification.Message);
        }

        [Fact]
        public void Dispose_CanBeCalledMultipleTimes()
        {
            // Arrange
            var service = new NotificationService();

            // Act & Assert - should not throw
            var exception = Record.Exception(() =>
            {
                service.Dispose();
                service.Dispose();
            });
            Assert.Null(exception);
        }
    }
}

