using System;
using System.Linq;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void SchoolContext_CanCreateInstance()
        {
            // Arrange & Act
            using var context = TestDbContextFactory.Create();

            // Assert
            Assert.NotNull(context);
            Assert.NotNull(context.Students);
            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.OfficeAssignments);
            Assert.NotNull(context.Notifications);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveStudent()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = DateTime.Parse("2023-01-01")
            };

            // Act
            context.Students.Add(student);
            context.SaveChanges();

            // Assert
            var retrieved = context.Students.First(s => s.LastName == "Student");
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal("Student", retrieved.LastName);
            Assert.Equal(DateTime.Parse("2023-01-01"), retrieved.EnrollmentDate);
        }

        [Fact]
        public void SchoolContext_CourseAssignment_HasCompositeKey()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();

            var instructor = new Instructor { FirstMidName = "Test", LastName = "Instructor", HireDate = DateTime.Now, CourseAssignments = new System.Collections.Generic.List<CourseAssignment>() };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var dept = new Department { Name = "TestDept", Budget = 100, StartDate = DateTime.Now, InstructorID = instructor.ID };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course { CourseID = 9999, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            context.Courses.Add(course);
            context.SaveChanges();

            // Act
            var ca = new CourseAssignment { CourseID = course.CourseID, InstructorID = instructor.ID };
            context.CourseAssignments.Add(ca);
            context.SaveChanges();

            // Assert
            var retrieved = context.CourseAssignments.Find(course.CourseID, instructor.ID);
            Assert.NotNull(retrieved);
            Assert.Equal(course.CourseID, retrieved.CourseID);
            Assert.Equal(instructor.ID, retrieved.InstructorID);
        }

        [Fact]
        public void SchoolContext_CanAddNotification()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var notification = new Notification
            {
                EntityType = "Student",
                EntityId = "1",
                Operation = "CREATE",
                Message = "Test notification",
                CreatedAt = DateTime.Now,
                CreatedBy = "Test",
                IsRead = false
            };

            // Act
            context.Notifications.Add(notification);
            context.SaveChanges();

            // Assert
            var retrieved = context.Notifications.First();
            Assert.Equal("Student", retrieved.EntityType);
            Assert.Equal("1", retrieved.EntityId);
            Assert.Equal("CREATE", retrieved.Operation);
            Assert.Equal("Test notification", retrieved.Message);
            Assert.False(retrieved.IsRead);
        }

        [Fact]
        public void SchoolContext_PersonInheritance_DiscriminatorWorks()
        {
            // Arrange
            using var context = TestDbContextFactory.Create();
            var student = new Student { FirstMidName = "S", LastName = "Stu", EnrollmentDate = DateTime.Now };
            var instructor = new Instructor { FirstMidName = "I", LastName = "Ins", HireDate = DateTime.Now, CourseAssignments = new System.Collections.Generic.List<CourseAssignment>() };

            context.Students.Add(student);
            context.Instructors.Add(instructor);
            context.SaveChanges();

            // Act
            var people = context.People.ToList();

            // Assert
            Assert.Contains(people, p => p.LastName == "Stu" && p is Student);
            Assert.Contains(people, p => p.LastName == "Ins" && p is Instructor);
        }
    }
}

