using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;

        public CoursesControllerTests()
        {
            _context = TestDbContextFactory.CreateWithData();
            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockEnv.Setup(e => e.WebRootPath).Returns("/tmp/webroot");
            _mockEnv.Setup(e => e.ContentRootPath).Returns("/tmp/contentroot");
            _mockLogger = new Mock<ILogger<CoursesController>>();
            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_ReturnsViewWithAllCourses()
        {
            // Act
            var result = _controller.Index() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result.Model as List<Course>;
            Assert.NotNull(model);
            Assert.Equal(3, model.Count);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            // Arrange
            var courseId = _context.Courses.First().CourseID;

            // Act
            var result = _controller.Details(courseId) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var course = result.Model as Course;
            Assert.NotNull(course);
            Assert.Equal(courseId, course.CourseID);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Details(null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithNewCourse()
        {
            // Act
            var result = _controller.Create() as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.IsType<Course>(result.Model);
        }

        [Fact]
        public void Create_Post_ValidCourse_RedirectsToIndex()
        {
            // Arrange
            var course = new Course
            {
                CourseID = 5555,
                Title = "New Course",
                Credits = 3,
                DepartmentID = _context.Departments.First().DepartmentID
            };

            // Act
            var result = _controller.Create(course, null) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Create_Post_ValidCourse_SavesToDB()
        {
            // Arrange
            var course = new Course
            {
                CourseID = 6666,
                Title = "Saved Course",
                Credits = 4,
                DepartmentID = _context.Departments.First().DepartmentID
            };

            // Act
            _controller.Create(course, null);

            // Assert
            var saved = _context.Courses.Find(6666);
            Assert.NotNull(saved);
            Assert.Equal("Saved Course", saved.Title);
            Assert.Equal(4, saved.Credits);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            // Arrange
            var course = new Course { CourseID = 7777, Title = "X", Credits = 3, DepartmentID = 1 };
            _controller.ModelState.AddModelError("Title", "Required");

            // Act
            var result = _controller.Create(course, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(course, result.Model);
        }

        [Fact]
        public void Create_Post_InvalidFileExtension_ReturnsViewWithError()
        {
            // Arrange
            var course = new Course { CourseID = 8888, Title = "TestCourse", Credits = 3, DepartmentID = 1 };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.exe");
            mockFile.Setup(f => f.Length).Returns(1000);

            // Act
            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_Post_FileTooLarge_ReturnsViewWithError()
        {
            // Arrange
            var course = new Course { CourseID = 8889, Title = "TestCourse", Credits = 3, DepartmentID = 1 };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB

            // Act
            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithCourse()
        {
            // Arrange
            var courseId = _context.Courses.First().CourseID;

            // Act
            var result = _controller.Edit(courseId) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var course = result.Model as Course;
            Assert.NotNull(course);
            Assert.Equal(courseId, course.CourseID);
        }

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Edit((int?)null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Edit_Get_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Edit(99999) as NotFoundResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_Post_ValidCourse_RedirectsToIndex()
        {
            // Arrange
            var existing = _context.Courses.First();
            _context.Entry(existing).State = EntityState.Detached;

            var course = new Course
            {
                CourseID = existing.CourseID,
                Title = "Updated Title",
                Credits = existing.Credits,
                DepartmentID = existing.DepartmentID
            };

            // Act
            var result = _controller.Edit(course, null) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidModelState_ReturnsView()
        {
            // Arrange
            var course = new Course { CourseID = 1050, Title = "X", Credits = 3, DepartmentID = 1 };
            _controller.ModelState.AddModelError("Title", "Required");

            // Act
            var result = _controller.Edit(course, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_Post_InvalidFileExtension_ReturnsViewWithError()
        {
            // Arrange
            var existing = _context.Courses.First();
            _context.Entry(existing).State = EntityState.Detached;

            var course = new Course { CourseID = existing.CourseID, Title = existing.Title, Credits = existing.Credits, DepartmentID = existing.DepartmentID };
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.exe");
            mockFile.Setup(f => f.Length).Returns(1000);

            // Act
            var result = _controller.Edit(course, mockFile.Object) as ViewResult;

            // Assert
            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithCourse()
        {
            // Arrange
            var courseId = _context.Courses.First().CourseID;

            // Act
            var result = _controller.Delete(courseId) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var course = result.Model as Course;
            Assert.NotNull(course);
            Assert.Equal(courseId, course.CourseID);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Delete((int?)null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesCourseAndRedirects()
        {
            // Arrange
            var course = _context.Courses.First();
            var courseId = course.CourseID;
            var countBefore = _context.Courses.Count();

            // Act
            var result = _controller.DeleteConfirmed(courseId) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Equal(countBefore - 1, _context.Courses.Count());
        }
    }
}

