using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Models.SchoolViewModels;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class InstructorsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly InstructorsController _controller;

        public InstructorsControllerTests()
        {
            _context = TestDbContextFactory.CreateWithData();
            _controller = new InstructorsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Index_NoParameters_ReturnsViewWithInstructors()
        {
            // Act
            var result = _controller.Index(null, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result.Model as InstructorIndexData;
            Assert.NotNull(model);
            Assert.NotNull(model.Instructors);
            Assert.Equal(3, model.Instructors.Count());
        }

        [Fact]
        public void Index_WithInstructorId_ShowsCourses()
        {
            // Arrange
            var instructorId = _context.Instructors.First().ID;

            // Act
            var result = _controller.Index(instructorId, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result.Model as InstructorIndexData;
            Assert.NotNull(model);
            Assert.NotNull(model.Courses);
        }

        [Fact]
        public void Index_WithInstructorAndCourseId_ShowsEnrollments()
        {
            // Arrange
            var instructor = _context.Instructors
                .Include(i => i.CourseAssignments)
                .First(i => i.CourseAssignments.Any());
            var courseId = instructor.CourseAssignments.First().CourseID;

            // Act
            var result = _controller.Index(instructor.ID, courseId) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var model = result.Model as InstructorIndexData;
            Assert.NotNull(model);
            Assert.NotNull(model.Enrollments);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithInstructor()
        {
            // Arrange
            var instructorId = _context.Instructors.First().ID;

            // Act
            var result = _controller.Details(instructorId) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var instructor = result.Model as Instructor;
            Assert.NotNull(instructor);
            Assert.Equal(instructorId, instructor.ID);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Details(null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Details_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Details(99999) as NotFoundResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void Create_Get_ReturnsViewWithInstructor()
        {
            // Act
            var result = _controller.Create() as ViewResult;

            // Assert
            Assert.NotNull(result);
            var instructor = result.Model as Instructor;
            Assert.NotNull(instructor);
            Assert.NotNull(instructor.CourseAssignments);
        }

        [Fact]
        public void Create_Post_ValidInstructor_RedirectsToIndex()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "New",
                LastName = "Instructor",
                HireDate = DateTime.Parse("2023-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };

            // Act
            var result = _controller.Create(instructor, null) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
        }

        [Fact]
        public void Create_Post_ValidInstructor_SavesToDB()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "Saved",
                LastName = "NewInstructor",
                HireDate = DateTime.Parse("2023-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };

            // Act
            _controller.Create(instructor, null);

            // Assert
            var saved = _context.Instructors.FirstOrDefault(i => i.LastName == "NewInstructor");
            Assert.NotNull(saved);
            Assert.Equal("Saved", saved.FirstMidName);
        }

        [Fact]
        public void Create_Post_WithSelectedCourses_AssignsCourses()
        {
            // Arrange
            var courseId = _context.Courses.First().CourseID;
            var instructor = new Instructor
            {
                FirstMidName = "Course",
                LastName = "Assigned",
                HireDate = DateTime.Parse("2023-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };

            // Act
            _controller.Create(instructor, new[] { courseId.ToString() });

            // Assert
            var saved = _context.Instructors
                .Include(i => i.CourseAssignments)
                .FirstOrDefault(i => i.LastName == "Assigned");
            Assert.NotNull(saved);
            Assert.Contains(saved.CourseAssignments, ca => ca.CourseID == courseId);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Inst",
                HireDate = DateTime.Now,
                CourseAssignments = new List<CourseAssignment>()
            };
            _controller.ModelState.AddModelError("LastName", "Required");

            // Act
            var result = _controller.Create(instructor, null) as ViewResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithInstructor()
        {
            // Arrange
            var instructorId = _context.Instructors.First().ID;

            // Act
            var result = _controller.Delete(instructorId) as ViewResult;

            // Assert
            Assert.NotNull(result);
            var instructor = result.Model as Instructor;
            Assert.NotNull(instructor);
            Assert.Equal(instructorId, instructor.ID);
        }

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            // Act
            var result = _controller.Delete(null) as StatusCodeResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal(400, result.StatusCode);
        }

        [Fact]
        public void Delete_Get_InvalidId_ReturnsNotFound()
        {
            // Act
            var result = _controller.Delete(99999) as NotFoundResult;

            // Assert
            Assert.NotNull(result);
        }

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesInstructorAndRedirects()
        {
            // Arrange  - use an instructor that has no office assignment or course assignments for simplicity
            var instructor = new Instructor
            {
                FirstMidName = "ToDelete",
                LastName = "Removable",
                HireDate = DateTime.Parse("2020-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var instructorId = instructor.ID;

            // Act
            var result = _controller.DeleteConfirmed(instructorId) as RedirectToActionResult;

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Index", result.ActionName);
            Assert.Null(_context.Instructors.Find(instructorId));
        }

        [Fact]
        public void DeleteConfirmed_InstructorIsAdministrator_NullsDepartmentReference()
        {
            // Arrange
            var instructor = new Instructor
            {
                FirstMidName = "Admin",
                LastName = "ToDel",
                HireDate = DateTime.Parse("2020-01-01"),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();

            var dept = new Department
            {
                Name = "TempDept",
                Budget = 100,
                StartDate = DateTime.Now,
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            var deptId = dept.DepartmentID;

            // Act
            _controller.DeleteConfirmed(instructor.ID);

            // Assert
            var updatedDept = _context.Departments.Find(deptId);
            Assert.NotNull(updatedDept);
            Assert.Null(updatedDept.InstructorID);
        }
    }
}

