using System;
using System.Linq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.CreateWithData();
            _controller = new NotificationsController(_context);
            // Drain the static queue
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
            svc.Dispose();
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            // Act
            var result = _controller.GetNotifications();

            // Assert
            Assert.NotNull(result);
            var jsonResult = result as JsonResult;
            Assert.NotNull(jsonResult);
            // Verify the value contains success = true
            dynamic value = jsonResult.Value;
            Assert.NotNull(value);
        }

        [Fact]
        public void GetNotifications_WithNotifications_ReturnsNotifications()
        {
            // Arrange - Send a notification via a temporary service
            var svc = new NotificationService();
            svc.SendNotification("Student", "1", "Test Student", EntityOperation.CREATE, "Admin");
            svc.Dispose();

            // Act
            var result = _controller.GetNotifications() as JsonResult;

            // Assert
            Assert.NotNull(result);
            Assert.NotNull(result.Value);
        }

        [Fact]
        public void GetNotifications_LimitsToTen()
        {
            // Arrange - Send more than 10 notifications
            var svc = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Student", i.ToString(), EntityOperation.CREATE, "Admin");
            }
            svc.Dispose();

            // Act
            var result = _controller.GetNotifications() as JsonResult;

            // Assert
            Assert.NotNull(result);
            Assert.NotNull(result.Value);
            // The response should contain at most 10 notifications
            var valueType = result.Value.GetType();
            var countProp = valueType.GetProperty("count");
            if (countProp != null)
            {
                var count = (int)countProp.GetValue(result.Value);
                Assert.True(count <= 10);
            }
        }

        [Fact]
        public void MarkAsRead_ValidId_ReturnsSuccess()
        {
            // Act
            var result = _controller.MarkAsRead(1) as JsonResult;

            // Assert
            Assert.NotNull(result);
            Assert.NotNull(result.Value);
            var valueType = result.Value.GetType();
            var successProp = valueType.GetProperty("success");
            if (successProp != null)
            {
                var success = (bool)successProp.GetValue(result.Value);
                Assert.True(success);
            }
        }

        [Fact]
        public void Index_ReturnsViewResult()
        {
            // Act
            var result = _controller.Index() as ViewResult;

            // Assert
            Assert.NotNull(result);
        }
    }
}

