using System;
using System.Collections.Generic;
using System.Linq;
using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            // Arrange
            var items = Enumerable.Range(1, 50).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(items, 1, 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(5, result.TotalPages);
        }

        [Fact]
        public void Create_SecondPage_ReturnsCorrectItems()
        {
            // Arrange
            var items = Enumerable.Range(1, 50).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(items, 2, 10);

            // Assert
            Assert.Equal(10, result.Count);
            Assert.Equal(2, result.PageIndex);
            Assert.Equal(11, result.First());
            Assert.Equal(20, result.Last());
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            // Arrange
            var items = Enumerable.Range(1, 50).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(items, 1, 10);

            // Assert
            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            // Arrange
            var items = Enumerable.Range(1, 50).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(items, 2, 10);

            // Assert
            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            // Arrange
            var items = Enumerable.Range(1, 50).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(items, 5, 10);

            // Assert
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_FirstPage_ReturnsTrue()
        {
            // Arrange
            var items = Enumerable.Range(1, 50).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(items, 1, 10);

            // Assert
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void TotalPages_CalculatesCorrectly()
        {
            // Arrange
            var items = Enumerable.Range(1, 25).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(items, 1, 10);

            // Assert
            Assert.Equal(3, result.TotalPages); // 25/10 = 2.5, ceiling = 3
        }

        [Fact]
        public void TotalPages_ExactDivision_NoExtraPage()
        {
            // Arrange
            var items = Enumerable.Range(1, 20).AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(items, 1, 10);

            // Assert
            Assert.Equal(2, result.TotalPages);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            // Arrange
            var items = Enumerable.Empty<int>().AsQueryable();

            // Act
            var result = PaginatedList<int>.Create(items, 1, 10);

            // Assert
            Assert.Empty(result);
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(0, result.TotalPages);
        }

        [Fact]
        public void Constructor_SetsProperties()
        {
            // Arrange & Act
            var list = new PaginatedList<string>(new List<string> { "a", "b" }, 10, 2, 5);

            // Assert
            Assert.Equal(2, list.PageIndex);
            Assert.Equal(2, list.TotalPages); // ceil(10/5) = 2
            Assert.Equal(2, list.Count);
            Assert.Contains("a", list);
            Assert.Contains("b", list);
        }
    }
}

