using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;

            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        public static SchoolContext CreateWithData(string? dbName = null)
        {
            var context = Create(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            // Add instructors (let EF assign IDs)
            var instructor1 = new Instructor { FirstMidName = "Kim", LastName = "Abercrombie", HireDate = DateTime.Parse("1995-03-11"), CourseAssignments = new List<CourseAssignment>() };
            var instructor2 = new Instructor { FirstMidName = "Fadi", LastName = "Fakhouri", HireDate = DateTime.Parse("2002-07-06"), CourseAssignments = new List<CourseAssignment>() };
            var instructor3 = new Instructor { FirstMidName = "Roger", LastName = "Harui", HireDate = DateTime.Parse("1998-07-01"), CourseAssignments = new List<CourseAssignment>() };
            context.Instructors.AddRange(instructor1, instructor2, instructor3);
            context.SaveChanges();

            // Add departments referencing instructor IDs
            var dept1 = new Department { Name = "English", Budget = 350000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = instructor1.ID };
            var dept2 = new Department { Name = "Mathematics", Budget = 100000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = instructor2.ID };
            context.Departments.AddRange(dept1, dept2);
            context.SaveChanges();

            // Add students (let EF assign IDs)
            var student1 = new Student { FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Parse("2010-09-01"), Enrollments = new List<Enrollment>() };
            var student2 = new Student { FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Parse("2012-09-01"), Enrollments = new List<Enrollment>() };
            var student3 = new Student { FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = DateTime.Parse("2013-09-01"), Enrollments = new List<Enrollment>() };
            context.Students.AddRange(student1, student2, student3);
            context.SaveChanges();

            // Add courses with explicit CourseIDs (DatabaseGeneratedOption.None)
            var course1 = new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = dept1.DepartmentID, Enrollments = new List<Enrollment>(), CourseAssignments = new List<CourseAssignment>() };
            var course2 = new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = dept2.DepartmentID, Enrollments = new List<Enrollment>(), CourseAssignments = new List<CourseAssignment>() };
            var course3 = new Course { CourseID = 1045, Title = "Calculus", Credits = 4, DepartmentID = dept2.DepartmentID, Enrollments = new List<Enrollment>(), CourseAssignments = new List<CourseAssignment>() };
            context.Courses.AddRange(course1, course2, course3);
            context.SaveChanges();

            // Add enrollments
            context.Enrollments.AddRange(
                new Enrollment { StudentID = student1.ID, CourseID = 1050, Grade = Grade.A },
                new Enrollment { StudentID = student1.ID, CourseID = 4022, Grade = Grade.C },
                new Enrollment { StudentID = student2.ID, CourseID = 1045, Grade = Grade.B }
            );
            context.SaveChanges();

            // Add course assignments
            context.CourseAssignments.AddRange(
                new CourseAssignment { CourseID = 1050, InstructorID = instructor1.ID },
                new CourseAssignment { CourseID = 4022, InstructorID = instructor2.ID },
                new CourseAssignment { CourseID = 1045, InstructorID = instructor3.ID }
            );
            context.SaveChanges();
        }
    }
}

